import java.lang.foreign.*;
import java.lang.invoke.MethodHandle;
import java.lang.invoke.VarHandle;

public class PanamaDemo {
    public static void main(String[] args) {
        // 1. Acquire the native linker
        Linker linker = Linker.nativeLinker();

        // 2. Find the standard 'strlen' function in the C standard library
        SymbolLookup stdlib = linker.defaultLookup();
        MethodHandle strlen = linker.downcallHandle(
            stdlib.lookup("strlen").get(),
            FunctionDescriptor.of(ValueLayout.JAVA_LONG, ValueLayout.ADDRESS)
        );

        // 3. Allocate native memory within a confined arena and invoke the function
        try (Arena arena = Arena.ofConfined()) {
            MemorySegment cString = arena.allocateUtf8String("Hello, Project Panama!");
            long length = (long) strlen.invoke(cString);
            System.out.println("String length calculated natively: " + length);
        } catch (Throwable e) {
            e.printStackTrace();
        }
    }
}
